        { "ESC-177c", "EST-004", "¿Qué nota definitiva tengo en Contabilidad?", "Contabilidad: 3.9." }
    };

    [Theory]
    [MemberData(nameof(PreguntasDeQ10ConResumen))]
    [Trait("CA", "CA-01")]
    [Trait("ESC", "ESC-177")]
    [Trait("ESC", "ESC-164")]
    [Trait("RF", "COMP-02")]
